import { ButtonGroupContext, ButtonGroupContextValue, POSITIONTAG } from './context';
import { Provide } from '@src/framework/runtime-context';
import { Slot, Slots, Uncontrollable, Vue2ValueFix } from '@src/framework/decorators';
import { generateUniqueId } from '@src/shared/unclassified/unique-id';
import { FormBaseComponent } from '@src/components/ks-form/FormBaseComponent';
import { Component, Element, Event, type EventEmitter, Host, Prop, State, Watch, h } from '@stencil/core';
import { FormContextValueReconcile } from '../ks-form/FormContextValueReconcile';
const prefix = 'button-group';

/**
 * @slot default - Slot for the `ks-button-group-item` elements rendered inside the group and used to determine button positions.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-button-group',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsButtonGroup extends FormBaseComponent<string[]> {
  protected static vModel = { prop: 'value', event: 'ksChange' };
  @Element() el!: HTMLKsButtonGroupElement;

  @Provide({
    context: ButtonGroupContext,
  })
  private buttonGroupContext: ButtonGroupContextValue = {
    htmlName: '',
    disabled: undefined,
    value: undefined,
    onValueChange: (value: string) => {
      if (this.multiple) {
        if (this.internalValueState?.includes(value)) {
          this.internalValueState = this.internalValueState.filter((item) => item !== value);
        } else {
          this.internalValueState = [...(this.internalValueState || []), value].sort();
        }
      } else {
        this.internalValueState = [value];
      }
    },
  };

  /** The htmlname of the group button. */
  @Prop() htmlName: string = generateUniqueId();
  /** Indicates whether the group button is disabled. When `true`, the user will not be able to interact with the buttons. */
  @Prop() @FormContextValueReconcile() disabled?: boolean;
  /** The default value of the group button when the component is first rendered. */
  @Prop() defaultValue?: string[];
  /** The current value of the group button. This determines the selected item(s) in the group. */
  @Prop() @Vue2ValueFix() @FormContextValueReconcile() value?: string[];

  @Uncontrollable('value', 'defaultValue', 'ksChange')
  @State()
  internalValueState?: string[];
  /** Whether the group allows selecting multiple items at the same time. */
  @Prop() multiple = false;
  /**
   * @deprecated please use `multiple` instead
   * [DEPRECATED] The current value of the group button.
   */
  @Prop() isMultiple?: boolean;

  @Watch('isMultiple')
  handleIsMultipleChange() {
    this.isMultiple !== undefined && (this.multiple = this.isMultiple);
  }

  /** Custom event triggered when the selected value changes. This event can be used to execute additional actions when the selection is modified. */
  @Event({ bubbles: false, composed: false }) ksChange!: EventEmitter<string[]>;

  @Slot({ slotname: '_default' }) private defaultSlots?: Slots;

  @Watch('htmlName')
  @Watch('disabled')
  @Watch('multiple')
  @Watch('internalValueState')
  handleContextValueChange() {
    this.buttonGroupContext = {
      ...this.buttonGroupContext,
      htmlName: this.htmlName,
      disabled: this.disabled,
      value: this.internalValueState,
      multiple: this.multiple,
    };
  }

  private handleDefaultSlotsChange() {
    const positionMap = (this.defaultSlots || []).reduce<WeakMap<HTMLKsButtonGroupItemElement, POSITIONTAG>>(
      (prev, cur, idx, slots) => {
        const currentGroupItem = cur as HTMLKsButtonGroupItemElement;
        if (idx === 0) {
          prev.set(currentGroupItem, POSITIONTAG.START);
        } else if (idx === slots.length - 1) {
          prev.set(currentGroupItem, POSITIONTAG.END);
        } else {
          prev.set(currentGroupItem, POSITIONTAG.COMMON);
        }
        return prev;
      },
      new WeakMap(),
    );
    this.buttonGroupContext = {
      ...this.buttonGroupContext,
      positionMap,
    };
  }

  componentWillLoad(): Promise<void> | void {
    this.handleContextValueChange();

    this.handleIsMultipleChange();
  }

  componentDidLoad(): void {
    this.handleDefaultSlotsChange();
  }

  render() {
    return (
      <Host class="KsButtonGroup">
        <div class={prefix} part="base">
          <slot />
        </div>
      </Host>
    );
  }
}
